#include "solver.h"
#include <stdio.h>
typedef struct {bool used,cancel;} State;
static int callback(void *p) {
    State *s=p;if(s->used)return 0;s->used=true;
    double start=solver_cpu_time();while(solver_cpu_time()-start<.01) {}
    return s->cancel;
}
int main(void) {
    unsigned failures=0;SolverOpts o=default_opts();o.probing=false;
    Solver *s=solver_new_with_opts(&o);if(!s)return 99;solver_new_var(s);
    State p={false,true};solver_set_terminate(s,&p,callback);
    lbool result=solver_solve_portfolio(s,.001);
    printf("one-shot cancellation: result=%d attempts=%u\n",result,s->portfolio_attempts);
    if(result!=UNDEF || s->portfolio_attempts!=1)failures|=1;
    solver_free(s);o.max_time=.001;s=solver_new_with_opts(&o);if(!s)return 99;
    solver_add_clause(s,NULL,0);p=(State){false,false};solver_set_terminate(s,&p,callback);
    result=solver_solve(s);printf("terminal callback CPU: result=%d interrupted=%d\n",result,s->interrupted);
    if(result!=UNDEF || !s->interrupted)failures|=2;
    solver_free(s);printf("regression failure mask=%u\n",failures);return (int)failures;
}
